const listBoards = `-- name: ListBoards :many

SELECT b.id, b.tenant_id, b.name, b.created_at, b.prefix, b.card_seq, b.archived_at, b.owner_user_id FROM boards b WHERE b.tenant_id = $1 AND b.archived_at IS NULL AND (
    b.owner_user_id = $2
    OR (b.owner_user_id IS NULL AND NOT EXISTS (SELECT 1 FROM board_grants g WHERE g.board_id = b.id))
    OR EXISTS (
        SELECT 1 FROM board_grants g WHERE g.board_id = b.id AND (
            g.subject_type = 'org'
            OR (g.subject_type = 'user' AND g.subject_id = $2)
            OR (g.subject_type = 'group' AND EXISTS (
                SELECT 1 FROM user_group_members ugm
                WHERE ugm.group_id = g.subject_id AND ugm.user_id = $2))))
    OR EXISTS (SELECT 1 FROM cards c WHERE c.board_id = b.id AND c.assignee_id = $2)
) ORDER BY b.created_at
`

type ListBoardsParams struct {
	TenantID uuid.UUID   `json:"tenant_id"`
	UserID   pgtype.UUID `json:"user_id"`
}

// Kanban: boards, columns, cards, checklists and dependencies.
//
// Split out of queries.sql, which had grown to 2309 lines -- four times the 600 the project
// allows (law 1.4). sqlc reads every file in this directory, so moving a query changes nothing
// about the generated API; only where it lives.
// Per-user visibility: owner, legacy (no owner and no grants = whole org), a grant (org/user/group),
// or a card assigned to the user on the board (automatic access).
func (q *Queries) ListBoards(ctx context.Context, arg ListBoardsParams) ([]Board, error) {
	rows, err := q.db.Query(ctx, listBoards, arg.TenantID, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Board
	for rows.Next() {
		var i Board
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.Name,
			&i.CreatedAt,
			&i.Prefix,
			&i.CardSeq,
			&i.ArchivedAt,
			&i.OwnerUserID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

